import{TouchError}from"../common/Errors.js";import{createIncrementalIdGenerator}from"../util/incremental-id-generator.js";export class Keyboard{constructor(){}}export const MouseButton=Object.freeze({Left:"left",Right:"right",Middle:"middle",Back:"back",Forward:"forward"});export class Mouse{constructor(){}}export class Touchscreen{idGenerator=createIncrementalIdGenerator();touches=[];constructor(){}removeHandle(t){const r=this.touches.indexOf(t);-1!==r&&this.touches.splice(r,1)}async tap(t,r){const e=await this.touchStart(t,r);await e.end()}async touchMove(t,r){const e=this.touches[0];if(!e)throw new TouchError("Must start a new Touch first");return await e.move(t,r)}async touchEnd(){const t=this.touches.shift();if(!t)throw new TouchError("Must start a new Touch first");await t.end()}}